import gzip
from pathlib import Path

from maniac.sources import manpages
from maniac.sources.manpages import (
    find_help_derived_manpages,
    find_installed_manpage_path,
    find_repo_manpage,
    is_help2man_manpage,
    read_manpage_source,
)


def test_is_help2man_manpage_detects_gzip_page(tmp_path: Path) -> None:
    manpage = tmp_path / "tool.1.gz"
    with gzip.open(manpage, "wt", encoding="utf-8") as file:
        file.write(
            '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n'
        )

    assert is_help2man_manpage(manpage)


def test_find_help_derived_manpages_scans_active_manpath(
    monkeypatch, tmp_path: Path
) -> None:
    manpath = tmp_path / "share" / "man"
    man1 = manpath / "man1"
    man1.mkdir(parents=True)
    generated = man1 / "generated.1"
    generated.write_text(
        '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n',
        encoding="utf-8",
    )
    localized = manpath / "fr" / "man1" / "generated.1"
    localized.parent.mkdir(parents=True)
    localized.write_text(
        '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n',
        encoding="utf-8",
    )
    (man1 / "help2man.1").write_text(
        '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n',
        encoding="utf-8",
    )
    (man1 / "vendor.1").write_text(".TH VENDOR 1\n", encoding="utf-8")
    (man1 / "index.db").write_text(
        '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n',
        encoding="utf-8",
    )
    calls: list[list[str]] = []
    scanned: list[None] = []
    totals: list[int] = []

    def fake_run(args: list[str], **kwargs: object) -> object:
        calls.append(args)
        return type("Result", (), {"returncode": 0, "stdout": str(manpath)})()

    monkeypatch.setattr(manpages.subprocess, "run", fake_run)

    assert find_help_derived_manpages(
        "/usr/bin/manpath",
        on_scan=lambda: scanned.append(None),
        on_start=totals.append,
    ) == [
        manpages.HelpDerivedManpage("generated", "1", generated),
        manpages.HelpDerivedManpage("help2man", "1", man1 / "help2man.1"),
    ]
    assert calls == [["/usr/bin/manpath"]]
    assert len(scanned) == 5
    assert totals == [5]


def test_find_repo_manpage_matches_bin_dash_pattern_in_man_dir(tmp_path: Path) -> None:
    man_dir = tmp_path / "man"
    man_dir.mkdir()
    manpage = man_dir / "tool-sub.1"
    manpage.write_text(".TH TOOL-SUB 1\n", encoding="utf-8")

    assert find_repo_manpage(tmp_path, "tool") == manpage


def test_find_repo_manpage_matches_at_repo_root(tmp_path: Path) -> None:
    manpage = tmp_path / "tool.6"
    manpage.write_text(".TH TOOL 6\n", encoding="utf-8")

    assert find_repo_manpage(tmp_path, "tool") == manpage


def test_find_repo_manpage_skips_help2man_generated_pages(tmp_path: Path) -> None:
    doc_dir = tmp_path / "doc"
    doc_dir.mkdir()
    (doc_dir / "tool.1").write_text(
        '.\\" DO NOT MODIFY THIS FILE!  It was generated by help2man 1.49.3.\n',
        encoding="utf-8",
    )

    assert find_repo_manpage(tmp_path, "tool") is None


def test_find_repo_manpage_ignores_unrelated_trees(tmp_path: Path) -> None:
    vendor_dir = tmp_path / "vendor" / "man"
    vendor_dir.mkdir(parents=True)
    (vendor_dir / "tool.1").write_text(".TH TOOL 1\n", encoding="utf-8")

    assert find_repo_manpage(tmp_path, "tool") is None


def test_find_repo_manpage_no_match_returns_none(tmp_path: Path) -> None:
    assert find_repo_manpage(tmp_path, "tool") is None


def test_find_repo_manpage_prefers_exact_name_over_subcommand_variant(
    tmp_path: Path,
) -> None:
    man_dir = tmp_path / "man" / "man1"
    man_dir.mkdir(parents=True)
    exact = man_dir / "fzf.1"
    exact.write_text(".TH FZF 1\n", encoding="utf-8")
    (man_dir / "fzf-tmux.1").write_text(".TH FZF-TMUX 1\n", encoding="utf-8")

    assert find_repo_manpage(tmp_path, "fzf") == exact


def test_find_installed_manpage_path_returns_first_hit(
    monkeypatch, tmp_path: Path
) -> None:
    target = tmp_path / "tool.1.gz"

    def fake_run(args: list[str], **kwargs: object) -> object:
        assert args == ["/usr/bin/man", "-w", "tool"]
        return type("Result", (), {"returncode": 0, "stdout": f"{target}\n"})()

    monkeypatch.setattr(manpages.subprocess, "run", fake_run)
    assert find_installed_manpage_path("/usr/bin/man", "tool") == target


def test_find_installed_manpage_path_missing_returns_none(monkeypatch) -> None:
    def fake_run(args: list[str], **kwargs: object) -> object:
        return type("Result", (), {"returncode": 1, "stdout": ""})()

    monkeypatch.setattr(manpages.subprocess, "run", fake_run)
    assert find_installed_manpage_path("/usr/bin/man", "nonexistent") is None


def test_read_manpage_source_decompresses_gzip(tmp_path: Path) -> None:
    manpage = tmp_path / "tool.1.gz"
    content = ".TH TOOL 1\n.SH NAME\ntool \\- demo\n"
    with gzip.open(manpage, "wt", encoding="utf-8") as file:
        file.write(content)

    assert read_manpage_source(manpage) == content


def test_read_manpage_source_reads_plain_file(tmp_path: Path) -> None:
    manpage = tmp_path / "tool.1"
    content = ".TH TOOL 1\n"
    manpage.write_text(content, encoding="utf-8")

    assert read_manpage_source(manpage) == content
